// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateExpression Create an owner expression through the trusted gateway
	// (POST /api/v1/admin/expressions)
	CreateExpression(ctx context.Context, request CreateExpressionRequestObject) (CreateExpressionResponseObject, error)
	// UpdateExpression Update, publish or archive an owner expression through the trusted gateway
	// (PATCH /api/v1/admin/expressions/{id})
	UpdateExpression(ctx context.Context, request UpdateExpressionRequestObject) (UpdateExpressionResponseObject, error)
	// GetReviewProgress Get owner review progress by Asia/Seoul date through the trusted gateway
	// (GET /api/v1/admin/progress)
	GetReviewProgress(ctx context.Context, request GetReviewProgressRequestObject) (GetReviewProgressResponseObject, error)
	// RecordReviewEvent Record one review rating and advance state through the trusted gateway
	// (POST /api/v1/admin/review-events)
	RecordReviewEvent(ctx context.Context, request RecordReviewEventRequestObject) (RecordReviewEventResponseObject, error)
	// ListDueReviews List published expressions due for review through the trusted gateway
	// (GET /api/v1/admin/reviews/due)
	ListDueReviews(ctx context.Context, request ListDueReviewsRequestObject) (ListDueReviewsResponseObject, error)
	// ListPublicExpressions List published expressions
	// (GET /api/v1/expressions)
	ListPublicExpressions(ctx context.Context, request ListPublicExpressionsRequestObject) (ListPublicExpressionsResponseObject, error)
	// GetPublicExpression Get one published expression
	// (GET /api/v1/expressions/{id})
	GetPublicExpression(ctx context.Context, request GetPublicExpressionRequestObject) (GetPublicExpressionResponseObject, error)
	// GetHealth Check process liveness
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReadiness Check dependency readiness
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

